P=int(open('p.txt').read())
shares=[tuple(map(int,l.split())) for l in open('shares.txt').read().splitlines()]
def lagrange(points, x=0):
    s=0
    for i,(xi,yi) in enumerate(points):
        num=1; den=1
        for j,(xj,_) in enumerate(points):
            if i!=j:
                num=num*(x-xj)%P; den=den*(xi-xj)%P
        s=(s+yi*num*pow(den,-1,P))%P
    return s
sec=lagrange(shares[:3])
print(sec.to_bytes((sec.bit_length()+7)//8,'big').decode())
